  return `<div class="twocol">${section('Quick reference',`${row('Annual planning notes','Review dates and recorded questions','finance-reference')}${row('Account reference','Recorded account details · Private','finance-reference')}${row('Card benefit terms','Source document and expiry dates','finance-reference')}`)}${section('Keep the source close',`<p>Each reference names its source and update date. Sensitive values stay hidden until you choose to reveal them.</p><div class="receipt">Source: sample reference<br>Updated: October 6<br>Account number: •••• 1234</div>${btn('materials','Open supporting documents','primary')}`)}</div>`;
