function selfReviewView() {
  return `<div class="twocol"><article class="document"><div class="eyebrow">System / Self-review</div><h2>A report you can inspect.</h2><p>The latest review separates observations, evidence and proposed changes. A suggestion is not an applied change.</p><h3>What the sample review found</h3><p>Related materials are easier to follow when the selected project remains visible. Two recurring workflows would benefit from a clearer recovery path.</p><h3>Proposed next steps</h3><p>Review the layout proposal. Inspect the affected workflows before deciding whether to change them.</p><div class="notice">Sample report only. This proof runs no review and modifies no source.</div></article><aside class="stack">${section('Evidence',`${row('Review scope','Affected workspaces and version','system-record')}${row('Observed outcomes','Results and unresolved questions','system-record')}`)}${section('Proposed changes',`${row('Project context visibility','Proposed · Not applied','system-record')}${btn('new-item','Prepare a review request','primary','data-value="Self-review request"')}`)}</aside></div>`;
}
