function applyLayout(){const main=$('.main');if(state.customized[viewKey()]){main?.classList.add('proof-focus');const material=$('.material-workspace');if(material)material.classList.add('focused');const local=$('.content .local-index');if(local){local.style.display='none';local.parentElement.style.gridTemplateColumns='1fr';}const filetree=$('.filetree');if(filetree){filetree.style.display='none';$('.code-layout').style.gridTemplateColumns='minmax(0,1fr) 250px';}}}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search();return;}if(e.key==='Escape'&&state.overlay){e.preventDefault();closeOverlay();return;}if(e.key==='Enter'&&e.target.matches('tr[data-act],.site-preview h2[data-act]')){e.preventDefault();e.target.click();return;}if(!state.overlay)return;const dialog=$('[role="dialog"]');const focusable=[...dialog.querySelectorAll('button:not(:disabled),input,textarea,select,a,[tabindex="0"]')].filter(el=>el.getClientRects().length&&!el.hidden);if(e.key==='Tab'){const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if((state.overlay==='switcher'||state.overlay==='search')&&['ArrowDown','ArrowUp','Enter'].includes(e.key)){const options=state.overlay==='switcher'?$$('[data-search]').filter(b=>!b.hidden):$$('.modal-search-results .list-row').filter(b=>!b.hidden);const i=options.indexOf(document.activeElement);if(e.key==='Enter'&&i<0&&document.activeElement.tagName==='INPUT'){e.preventDefault();options[0]?.click();}else if(e.key!=='Enter'){e.preventDefault();options[(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus();}}});
